// Describes the communities of a graph generated by ../graph, for the
// interactive community map: their name, organizations, top members, position
// and color.
//
// Colors are indexes in the categorical palette of the site. They are kept
// from the previous version of the graph when a community has mostly the same
// members, and otherwise chosen to differ from the nearby communities.

const PALETTE_SIZE = 8;

// The organization of each username, from the organization of their emails.
export function UsernameOrganizations(organizations_emails) {
  const counts = {};
  for (const [organization, emails] of Object.entries(organizations_emails)) {
    if (organization === "Unknown") {
      continue;
    }
    for (const email of emails) {
      const username = email.split("@")[0];
      counts[username] ||= {};
      counts[username][organization] = (counts[username][organization] || 0) + 1;
    }
  }

  const out = {};
  for (const [username, by_organization] of Object.entries(counts)) {
    out[username] = Object.entries(by_organization)
      .sort((a, b) => b[1] - a[1])[0][0];
  }
  return out;
}

// Adds `communities` to `graph`, and replaces the cluster of each node by the
// index of its community.
export function DescribeCommunities(graph, organizations, previous) {
  const clusters = new Map();
  for (const node of graph.nodes) {
    const [label, x, y, size, cluster] = node;
    if (!clusters.has(cluster)) {
      clusters.set(cluster, []);
    }
    clusters.get(cluster).push({ label, x, y, size, node });
  }

  // The largest communities first.
  const weight = members => members.reduce((sum, m) => sum + m.size * m.size, 0);
  const communities = [...clusters.values()]
    .sort((a, b) => weight(b) - weight(a))
    .map((members, id) => {
      members.sort((a, b) => b.size - a.size);
      for (const member of members) {
        member.node[4] = id;
      }

      const [x, y] = DensestPoint(members);

      const by_organization = {};
      for (const member of members) {
        const organization = organizations[member.label];
        if (organization) {
          by_organization[organization] = (by_organization[organization] || 0) + 1;
        }
      }
      const known = Object.values(by_organization).reduce((a, b) => a + b, 0);
      const top_organizations = Object.entries(by_organization)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([organization, count]) => [organization, +(count / known).toFixed(2)]);

      return {
        id,
        name: Name(members, top_organizations),
        x: +x.toFixed(4),
        y: +y.toFixed(4),
        size: members.length,
        members: members.slice(0, 5).map(m => m.label),
        organizations: top_organizations,
        color: -1,
        all_members: members.map(m => m.label),
      };
    });

  AssignColors(communities, previous);

  for (const community of communities) {
    delete community.all_members;
  }
  graph.communities = communities;
  return graph;
}

// The position of the member with the most (weighted) members around it. The
// members of a community can be spread, so their average position can be far
// from all of them.
function DensestPoint(members) {
  const radius = 0.08;
  let best = members[0];
  let best_density = -1;
  for (const candidate of members) {
    let density = 0;
    for (const member of members) {
      const d = Math.hypot((candidate.x - member.x) / 2, candidate.y - member.y);
      if (d < radius) {
        density += member.size * member.size * (1 - d / radius);
      }
    }
    if (density > best_density) {
      best = candidate;
      best_density = density;
    }
  }
  return [best.x, best.y];
}

// A community is named after its organization, when it is not the main one of
// the project, or else after its top members.
function Name(members, top_organizations) {
  const [organization, share] = top_organizations[0] || [];
  if (organization && share >= 0.4 &&
      !["Google", "Individuals"].includes(organization)) {
    return organization;
  }
  return members.slice(0, 2).map(m => m.label).join(" · ");
}

function AssignColors(communities, previous) {
  // Keep the color of the previous community sharing the most members.
  if (previous?.communities && previous?.nodes) {
    const previous_members = previous.communities.map(() => new Set());
    for (const [label, , , , community] of previous.nodes) {
      previous_members[community]?.add(label);
    }

    const taken = new Set();
    for (const community of communities) {
      let best = null;
      let best_score = 0.3;
      previous.communities.forEach((candidate, index) => {
        if (taken.has(index)) {
          return;
        }
        const members = previous_members[index];
        const shared = community.all_members.filter(m => members.has(m)).length;
        const score = shared / (community.all_members.length + members.size - shared);
        if (score > best_score) {
          best = index;
          best_score = score;
        }
      });
      if (best !== null) {
        taken.add(best);
        community.color = previous.communities[best].color;
      }
    }
  }

  // Give the others a color the nearby communities don't have.
  const distance = (a, b) => Math.hypot((a.x - b.x) / 2, a.y - b.y);
  for (const community of communities) {
    if (community.color >= 0) {
      continue;
    }
    const used = new Map();
    for (const other of communities) {
      if (other === community || other.color < 0) {
        continue;
      }
      // Nearby and large communities count the most.
      const penalty = other.size / (0.01 + distance(community, other));
      used.set(other.color, (used.get(other.color) || 0) + penalty);
    }
    let best = 0;
    for (let color = 1; color < PALETTE_SIZE; ++color) {
      if ((used.get(color) || 0) < (used.get(best) || 0)) {
        best = color;
      }
    }
    community.color = best;
  }
}
